vars.program:
state.?secret.api_token.orValue(state.?api_token.orValue("")).as(api_token,
request("POST", state.auth_url).with({
  "Header": {"Authorization": ["Basic " + (":" + api_token).base64()]},
}).do_request().as(auth,
  auth.StatusCode != 200 && auth.StatusCode != 201 ?
    state.with({
      "events": [{"error": {"message": "Scalingo tokens/exchange : HTTP " + string(auth.StatusCode)}}],
      "want_more": false,
    })
  :
    auth.Body.decode_json().token.as(jwt,
      state.with({
        "events": state.bases.map(base,
          request("POST", state.url + "/v1/apps/" + base.app + "/addons/" + base.addon_id + "/token").with({
            "Header": {"Authorization": ["Bearer " + jwt], "Accept": ["application/json"]},
          }).do_request().as(jeton,
            jeton.StatusCode != 200 && jeton.StatusCode != 201 ?
              dyn([{"error": {"message": "Scalingo token de la base " + base.nom + " : HTTP " + string(jeton.StatusCode)}, "scalingo": {"database": {"nom": base.nom}}, "labels": {"base": base.nom}}])
            : !jeton.Body.decode_json().?addon.?token.hasValue() ?
              dyn([{"error": {"message": "Scalingo token de la base " + base.nom + " : réponse sans addon.token"}, "scalingo": {"database": {"nom": base.nom}}, "labels": {"base": base.nom}}])
            :
              request("GET", state.db_api_url + "/api/databases/" + base.addon_id + "/metrics").with({
                "Header": {
                  "Authorization": ["Bearer " + jeton.Body.decode_json().addon.token],
                  "Accept": ["application/json"],
                },
              }).do_request().as(resp,
                resp.StatusCode != 200 ?
                  dyn([{"error": {"message": "Scalingo métriques de la base " + base.nom + " : HTTP " + string(resp.StatusCode)}, "scalingo": {"database": {"nom": base.nom}}, "labels": {"base": base.nom}}])
                : !resp.Body.decode_json().?instances_metrics.hasValue() ?
                  dyn([{"error": {"message": "Scalingo métriques de la base " + base.nom + " : réponse sans instances_metrics"}, "scalingo": {"database": {"nom": base.nom}}, "labels": {"base": base.nom}}])
                :
                  dyn(resp.Body.decode_json().as(m,
                    m.instances_metrics.map(id, m.instances_metrics[id]).map(i, {
                      "labels": {"base": base.nom},
                      "scalingo": {
                        "database": {
                          "nom": base.nom,
                          "app": base.app,
                          "addon_id": base.addon_id,
                          "instance": i.instance_id,
                          "role": i.real_disk_size > 0.0 ? "donnees" : "auxiliaire",
                        }.with(has(base.connexions_max) ? {"connexions_max": base.connexions_max} : {})
                        .with(m.?database_stats.?data_size.hasValue() ? {"data_size": {"bytes": int(m.database_stats.data_size)}} : {})
                        .with(has(state.ca_expire_le) ? {"ca_expire_le": state.ca_expire_le} : {}),
                        "cpu": {"usage": i.cpu.usage_in_percents},
                        "memory": {
                          "usage": {"bytes": int(i.memory.memory_usage)},
                          "limit": {"bytes": int(i.memory.memory_limit)},
                          "highest": {"bytes": int(i.memory.max_memory_usage)},
                          "pct": i.memory.memory_limit > 0.0 ? double(i.memory.memory_usage) / double(i.memory.memory_limit) : 0.0,
                        },
                        "swap": {"usage": {"bytes": int(i.memory.swap_usage)}},
                        "disk": {
                          "usage": {"bytes": int(i.real_disk_size)},
                          "inclus": {"bytes": int(base.disque_inclus_octets)},
                          "pct": base.disque_inclus_octets > 0 ? double(i.real_disk_size) / double(base.disque_inclus_octets) : 0.0,
                        },
                      },
                    })
                  ))
              )
          )
        ).flatten(),
        "want_more": false,
      })
    )
)
)

vars.state:
auth_url: https://auth.scalingo.com/v1/tokens/exchange
db_api_url: https://db-api.osc-secnum-fr1.scalingo.com
ca_expire_le: "@@CA_EXPIRE_LE@@"
bases:
  - {app: pass-emploi-api-perf, addon_id: "@@ADDON_ID:postgresql-api-perf@@", nom: postgresql-api-perf, disque_inclus_octets: @@DISQUE_INCLUS:postgresql-api-perf@@, connexions_max: @@CONNEXIONS_MAX:postgresql-api-perf@@}
  - {app: pass-emploi-api-perf, addon_id: "@@ADDON_ID:redis-api-perf@@", nom: redis-api-perf, disque_inclus_octets: @@DISQUE_INCLUS:redis-api-perf@@}
  - {app: pass-emploi-connect-perf, addon_id: "@@ADDON_ID:redis-connect-perf@@", nom: redis-connect-perf, disque_inclus_octets: @@DISQUE_INCLUS:redis-connect-perf@@}
